export const BODY: string = "\n<p>فیویکن ایک تصویر نہیں ہے۔ یہ مختلف سائز پر تصاویر کا خاندان ہے، ہر ایک براؤزر یا آلے میں مختلف جگہ کی خدمت کرتا ہے۔ سب سے چھوٹا 16 بائی 16 ہے، سب سے بڑا 512 بائی 512 ہے۔</p>\n<p>یہ سمجھنا کہ کون سا سائز کہاں جاتا ہے آپ کو دو کلاسک ناکامیوں سے بچاتا ہے: دھندلا ٹیب آئیکن اور پکسلی ہوم اسکرین آئیکن۔ یہ گائیڈ ہر سائز سے گزرتی ہے۔</p>\n<p>یہ تمام سائز فیویکن جنریٹر میں ایک اپ لوڈ سے آتے ہیں۔ آپ کو ہر سائز ہاتھ سے ایکسپورٹ کرنے کی کبھی ضرورت نہیں۔ پیک میں کیا ہے یہ جاننا، تاہم، اسے انسٹال اور جانچنے میں مدد کرتا ہے۔</p>\n<h2 id=\"the-16-pixel-tab-icon\">16 پکسل ٹیب آئیکن</h2>\n<p>سولہ بائی سولہ پکسل وہ سائز ہے جس پر فیویکن پیدا ہوا تھا، اور یہ پھر بھی وہ سائز ہے جسے زیادہ تر لوگ سب سے زیادہ دیکھتے ہیں۔ یہ صفحے کے عنوان کے ساتھ براؤزر ٹیب میں بیٹھتا ہے۔</p>\n<p>اس سائز پر صرف جرات مند ترین شکلیں بچتی ہیں۔ ایک حرف، ٹھوس علامت، یا زیادہ کنٹراسٹ شکل صاف پڑھتی ہے۔ پتلی لکیریں غائب ہو جاتی ہیں، گریڈینٹ چپٹے ہو جاتے ہیں۔</p>\n<p>ہر براؤزر ٹیب بار میں 16 پکسل آئیکن استعمال کرتا ہے، اور زیادہ تر اسے بک مارک مینیو اور تاریخ فہرست میں بھی استعمال کرتے ہیں۔ یہ پیک میں سب سے محنتی سائز ہے، ہر روز دیکھا جاتا ہے۔</p>\n<p>جب آپ اپنا آئیکن چیک کریں تو کسی اور چیز سے پہلے 16 پکسل پیش نظارہ دیکھیں۔ اگر نشان وہاں پہچاننے کے قابل ہو تو یہ ہر جگہ پہچاننے کے قابل ہو گا۔ اگر یہ وہاں دھندلا ہو تو یہ ہر جگہ دھندلا ہو گا۔</p>\n<h2 id=\"the-32-pixel-retina-tab-icon\">32 پکسل ریٹینا ٹیب آئیکن</h2>\n<p>بتیس بائی بتیس پکسل ٹیب آئیکن کا ریٹینا ورژن ہے۔ ہائی ڈینسٹی اسکرین ایک ہی جگہ میں دوگنا جسمانی پکسل پیک کرتی ہیں، اس لیے براؤزر تیز ٹیب آئیکن کے لیے بڑی فائل چاہتے ہیں۔</p>\n<p>معیاری اسکرین پر 32 پکسل آئیکن 16 تک نیچے سکیل ہوتا ہے اور چھوٹی فائل جیسا لگتا ہے۔ ریٹینا اسکرین پر یہ مکمل تیزی سے رینڈر ہوتا ہے، تیز کناروں کے ساتھ۔</p>\n<p>ICO کنٹینر 16 اور 32 پکسل دونوں ورژن رکھتا ہے، اس لیے براؤزر اس اسکرین کے لیے درست چنتا ہے جس پر یہ چل رہا ہے۔ آپ کو ان کے درمیان چننے کی ضرورت نہیں۔</p>\n<p>16 پکسل کے لیے ڈیزائن شدہ نشان 32 پر ٹھیک کام کرتا ہے، کیونکہ بڑا سائز صرف تیزی بڑھاتا ہے۔ الٹا سچ نہیں ہے: جس نشان کو پڑھنے کے لیے 32 پکسل تفصیل چاہیے وہ 16 پر ناکام ہوتا ہے۔</p>\n<h2 id=\"the-48-pixel-shortcut-icon\">48 پکسل شارٹ کٹ آئیکن</h2>\n<p>اڑتالیس بائی اڑتالیس پکسل وہ سائز ہے جسے Windows ڈیسک ٹاپ شارٹ کٹ اور ٹاسک بار پن کے لیے استعمال کرتا ہے۔ جب کوئی آپ کی سائٹ کو ڈیسک ٹاپ پر گھسیٹے یا ٹاسک بار پر پن کرے تو یہ آئیکن ظاہر ہوتا ہے۔</p>\n<p>یہ کچھ براؤزر بک مارک مینیجر اور پرانے براؤزر میں ایڈریس بار میں بھی ظاہر ہوتا ہے۔ یہ درمیانی سائز ہے: 16 سے تھوڑی زیادہ تفصیل دکھانے کے لیے بڑا، مگر پھر بھی چھوٹا۔</p>\n<p>ICO فائل چھوٹے سائز کے ساتھ 48 پکسل سائز بھی شامل کرتی ہے، اس لیے ڈیسک ٹاپ شارٹ کٹ کو کھینچی گئی 16 پکسل فائل کے بجائے مناسب آئیکن ملتا ہے۔ کھینچی گئی آئیکن نرم اور شوقیہ لگتی ہے۔</p>\n<p>زیادہ تر سائٹیں اس سائز کے بارے میں کبھی نہیں سوچتیں، اور زیادہ تر زائرین اسے شعوری طور پر کبھی نہیں دیکھتے۔ یہ اس دن اہمیت رکھتا ہے جب کوئی آپ کی سائٹ کو ٹاسک بار پر پن کرے اور اسے دیکھے۔</p>\n<h2 id=\"the-64-and-96-pixel-sizes\">64 اور 96 پکسل سائز</h2>\n<p>چونسٹھ اور 96 پکسل آئیکن درمیانی سیاق کی خدمت کرتے ہیں: بڑی بک مارک ٹائل، براؤزر نیا ٹیب صفحہ، اور کچھ ایکسٹینشن انٹرفیس۔ یہ وہ سائز ہیں جو خلا بھرتے ہیں۔</p>\n<p>64 پکسل پر لوگو 16 کے مقابلے میں تھوڑی زیادہ شخصیت لے کر آ سکتا ہے۔ دو لہجے والا نشان یا پس منظر شکل والا سادہ علامت اچھی طرح پڑھتا ہے۔ 96 پکسل پر آئیکن میں اور بھی جگہ ہوتی ہے۔</p>\n<p>یہ سائز بھی ICO کنٹینر کے اندر رہتے ہیں، اس لیے انہیں بھیجنے میں کچھ اضافی نہیں لگتا۔ براؤزر اپنی ضرورت کے قریب ترین سائز چنتا ہے اور باقی کو سکیل کرتا ہے۔</p>\n<p>ڈیزائن کرتے وقت آپ کو ان سائز کے بارے میں شاذ و نادر ہی سوچنے کی ضرورت ہوتی ہے، کیونکہ جو کچھ 16 اور 180 پر کام کرے وہ 64 اور 96 پر کام کرے گا۔ وہ اس لیے ہیں تاکہ کوئی خلا نہ رہے۔</p>\n<h2 id=\"the-180-pixel-apple-touch-icon\">180 پکسل Apple Touch Icon</h2>\n<p>ایک سو اسی بائی 180 پکسل Apple Touch Icon ہے، جو اس وقت استعمال ہوتا ہے جب iPhone یا iPad صارف آپ کی سائٹ کو ہوم اسکرین میں بڑھائے۔ یہ پہلا سائز ہے جہاں آپ کا آئیکن بڑا دکھایا جاتا ہے۔</p>\n<p>Apple اس آئیکن میں شفافیت کو نظر انداز کرتا ہے اور شفاف علاقوں کو سیاہ سے بھرتا ہے۔ شفاف پس منظر والا لوگو سیاہ کونے پاتا ہے جو غلطی کی طرح لگتے ہیں۔</p>\n<p>Apple ہوم اسکرین آئیکن پر اپنا گول کونے والا ماسک بھی بڑھاتا ہے، اس لیے آپ کی 180 پکسل تصویر کے کونے سسٹم شکل کے پیچھے چھپ جاتے ہیں۔ اسے ذہن میں رکھ کر ڈیزائن کریں۔</p>\n<p>Apple Touch Icon PNG فائل ہے، ICO کنٹینر سے الگ۔ یہ HTML اسنیپٹ سے وقف لنک ٹیگ سے لنک ہوتا ہے، اور براؤزر اسے تب لیتا ہے جب صارف سائٹ کو محفوظ کرے۔</p>\n<h2 id=\"the-192-pixel-android-icon\">192 پکسل Android آئیکن</h2>\n<p>ایک سو بانوے بائی 192 پکسل Android ہوم اسکرین آئیکن ہے، جو ویب مینی فیسٹ میں درج ہے۔ جب Android صارف آپ کی سائٹ کو ہوم اسکرین میں بڑھائے تو یہ آئیکن ظاہر ہوتا ہے۔</p>\n<p>Android آلے اور لانچر کے لحاظ سے آئیکن پر ماسک لگاتا ہے، اس لیے محفوظ علاقہ اہمیت رکھتا ہے۔ نشان کو اس کے گرد پیڈنگ کے ساتھ بیچ میں رکھیں، کیونکہ لانچر کناروں کو کاٹ سکتا ہے۔</p>\n<p>192 پکسل آئیکن انسٹال پرامپٹ اور کچھ آلات پر ایپ دراز میں سائٹ کے لیے بھی استعمال ہوتا ہے۔ اسے ایپ آئیکن کی طرح لگنا چاہیے، سکڑے ہوئے لوگو کی طرح نہیں۔</p>\n<p>Apple آئیکن کے برعکس Android آئیکن شفافیت استعمال کر سکتا ہے، مگر ٹھوس پس منظر پھر بھی محفوظ انتخاب ہے۔ ٹھوس بھرنا ضمانت دیتا ہے کہ آئیکن ہر لانچر پر ایک جیسا لگے۔</p>\n<h2 id=\"the-512-pixel-android-icon\">512 پکسل Android آئیکن</h2>\n<p>پانچ سو بارہ بائی 512 پکسل پیک میں سب سے بڑا سائز ہے، جو Android اسپلش اسکرین اور انسٹال پرامپٹ کے لیے استعمال ہوتا ہے۔ جب صارف آپ کی انسٹال شدہ ویب ایپ کھولے تو یہ آئیکن بڑا دکھایا جاتا ہے۔</p>\n<p>اس سائز پر ماخذ تصویر کی ہر خامی نظر آتی ہے۔ 512 پکسل تک کھینچا گیا کم ریزولوشن لوگو نرم لگتا ہے، اور کمپریشن آرٹفیکٹ والا JPEG دھبے دکھاتا ہے۔</p>\n<p>کم از کم 512 پکسل کے ماخذ سے شروع کریں، یا SVG سے، تاکہ سب سے بڑا آئیکن سب سے چھوٹے جتنا تیز رینڈر ہو۔ ویکٹر ماخذ یہاں مثالی ہے کیونکہ یہ صاف پیمانہ کرتا ہے۔</p>\n<p>512 پکسل آئیکن وہ فائل بھی ہے جسے بہت سے سائٹ بلڈر مانگتے ہیں جب آپ ڈیش بورڈ میں سائٹ آئیکن سیٹ کریں۔ اس PNG کو اپ لوڈ کرنا بلڈر کو بڑا، صاف ماخذ دیتا ہے۔</p>\n<h2 id=\"how-the-ico-container-works\">ICO کنٹینر کیسے کام کرتا ہے</h2>\n<p>ICO فارمیٹ کنٹینر ہے جو ایک فائل میں مختلف سائز کی کئی تصاویر رکھتا ہے۔ عام favicon.ico میں 16، 32، 48، اور کبھی 64 پکسل ورژن ہوتے ہیں۔</p>\n<p>جب براؤزر کو آئیکن چاہیے تو یہ ICO فائل کھولتا ہے، دستیاب سائز دیکھتا ہے، اور اپنی ضرورت کے قریب ترین چنتا ہے۔ اسی لیے ایک فائل بہت سے سیاق کی خدمت کر سکتی ہے۔</p>\n<p>جنریٹر کی بنائی گئی ICO فائل حقیقی کئی فریم والی ICO بائنری ہے۔ یہ فرق اہمیت رکھتا ہے کیونکہ ICO ایکسٹینشن والا نام بدلا ہوا PNG کچھ براؤزر کو دھوکا دیتا ہے اور دوسروں میں ناکام ہوتا ہے۔</p>\n<p>جدید براؤزر PNG فیویکن بھی سیدھا استعمال کر سکتے ہیں، اسی لیے پیک میں PNG فائلیں بھی شامل ہیں۔ ICO فائل اپنی طویل تاریخ کی وجہ سے ڈیفالٹ رہتی ہے: براؤزر اسے سائٹ روٹ پر مانگتے ہیں چاہے اسنیپٹ نہ ہو۔</p>\n<h2 id=\"which-size-does-what\">کون سا سائز کیا کرتا ہے: فوری نقشہ</h2>\n<p>ٹیب آئیکن 16 پکسل ہے، ریٹینا اسکرین کے لیے 32 پکسل۔ ڈیسک ٹاپ شارٹ کٹ اور ٹاسک بار پن 48 پکسل استعمال کرتے ہیں۔ بڑی بک مارک ٹائل اور نیا ٹیب صفحہ 64 اور 96 استعمال کرتے ہیں۔</p>\n<p>ہر سائز مختلف دیکھنے کا فاصلہ ہے۔ ٹیب آئیکن بہت سے ٹیب کے درمیان ایک نظر میں دیکھا جاتا ہے، ہوم اسکرین آئیکن ایپس کے درمیان جان بوجھ کر دیکھا جاتا ہے، اور اسپلش اسکرین آئیکن بڑا اور اکیلا دیکھا جاتا ہے۔</p>\n<p>پیک ہر سیاق کو پانچ فائلوں سے پورا کرتا ہے: ICO کنٹینر، Apple Touch PNG، دو Android PNG، اور مینی فیسٹ جو ان کی طرف اشارہ کرتا ہے۔ کچھ اور نہیں چاہیے۔</p>\n<p>اگر آپ کو پیک سے کوئی سائز غائب ملے تو ہاتھ سے جوڑنے کے بجائے دوبارہ بنائیں۔ ہاتھ سے بڑھائی گئی فائل غلط ابعاد یا غلط فارمیٹ لے کر آ سکتی ہے۔</p>\n<h2 id=\"designing-for-every-size\">ہر سائز کے لیے ڈیزائن کرنا</h2>\n<p>پہلے سب سے چھوٹے سائز کے لیے ڈیزائن کریں۔ اگر نشان 16 پکسل پر پڑھے تو یہ ہر بڑے سائز پر پڑھے گا، کیونکہ بڑے سائز صرف جگہ اور تیزی بڑھاتے ہیں۔ اگر یہ 16 پر ناکام ہو تو یہ کہیں کام نہیں کرے گا۔</p>\n<p>ایک جرات مند شکل، ایک یا دو رنگ، اور مضبوط کنٹراسٹ استعمال کریں۔ ٹھوس پس منظر پر برانڈ رنگ میں واحد ابتدائی حرف سب سے قابل اعتماد فیویکن ڈیزائن ہے۔</p>\n<p>بھیجنے سے پہلے نشان کو 16، 180، اور 512 پکسل پر ٹیسٹ کریں۔ وہ تین سائز ٹیب، ہوم اسکرین، اور اسپلش اسکرین کی نمائندگی کرتے ہیں۔ اگر ڈیزائن ان تینوں سے بچے تو یہ تیار ہے۔</p>\n<p>جب لوگو کو کافی آسان نہ بنایا جا سکے تو پوری چیز کے بجائے اس کی تفصیل استعمال کریں۔ لوگو سے علامت، واحد حرف، یا سب سے پہچاننے والی شکل اکثر پورے لوگو سے بہتر کام کرتی ہے۔</p>\n<h2 id=\"checking-your-pack\">اپنا پیک چیک کرنا</h2>\n<p>بنانے کے بعد ZIP کھولیں اور تصدیق کریں کہ ICO فائل، Apple Touch PNG، 192 اور 512 پکسل Android PNG، اور مینی فیسٹ سب موجود ہیں۔ غائب فائل کا مطلب نامکمل پیک ہے۔</p>\n<p>پیک کو اپنی سائٹ پر انسٹال کریں، پھر اصل فون پر ٹیب آئیکن، بک مارک آئیکن، اور ہوم اسکرین آئیکن چیک کریں۔ ہر چیک مختلف سائز جانچتا ہے، اور ساتھ مل کر وہ پورا پیک جانچتے ہیں۔</p>\n<p>اگر پرانا آئیکن رہے تو براؤزر کیشے صاف کریں، اور نئے زائرین کو کیا نظر آتا ہے یہ دیکھنے کے لیے پرائیویٹ ونڈو میں ٹیسٹ کریں۔ پرائیویٹ ونڈو میں خالی کیشے ہوتا ہے، اس لیے یہ تازہ نظارہ دکھاتی ہے۔</p>\n<p>اگر ایک سائز غلط لگے جبکہ دوسرے درست لگیں تو ماخذ تصویر عام طور پر وجہ ہوتی ہے۔ کم ریزولوشن ماخذ 512 پکسل پر ناکام ہوتا ہے، اور تفصیلی ماخذ 16 پکسل پر ناکام ہوتا ہے۔</p>\n<h2 id=\"quick-reference\">فوری حوالہ: ایک نظر میں فیویکن سائز</h2>\n<p>ٹیب: 16 پکسل، ریٹینا 32۔ ڈیسک ٹاپ شارٹ کٹ: 48۔ بک مارک ٹائل: 64 اور 96۔ Apple ہوم اسکرین: 180۔ Android ہوم اسکرین: 192۔ Android اسپلش اور انسٹال: 512۔</p>\n<p>پہلے 16 پکسل کے لیے ڈیزائن کریں، کم از کم 512 پکسل کے ماخذ یا SVG سے شروع کریں، اور Apple آئیکن کو ٹھوس پس منظر دیں۔ ٹیب، بک مارک، اور ہوم اسکرین ٹیسٹ کریں۔</p>\n<p>مکمل گائیڈ کے لیے <a href=\"/ur/blog/favicon-generator-rehnumai/\">Favicon Generator: Complete Guide</a> پڑھیں، اور مرحلہ بہ مرحلہ بنانے کے لیے <a href=\"/ur/blog/favicon-kaise-banayein/\">How to Create a Favicon</a> پڑھیں۔ اپنا پیک <a href=\"/ur/favicon-generator/\">favicon generator</a> سے بنائیں۔</p>\n";

